SourceCode.Declaration:
[DataContract]
public class MXGSRequest
{
    str     code;
    boolean dryRun;
    int     maxLoopIterations;
    str     functionName;
    List    arguments;
    boolean noLog;
}

Method.Source:
[DataMember("Code")]
public str parmCode(str _code = code)
{
    code = _code;
    return code;
}

[DataMember("DryRun")]
public boolean parmDryRun(boolean _dryRun = dryRun)
{
    dryRun = _dryRun;
    return dryRun;
}

[DataMember("MaxLoopIterations")]
public int parmMaxLoopIterations(int _maxLoopIterations = maxLoopIterations)
{
    maxLoopIterations = _maxLoopIterations;
    return maxLoopIterations;
}

[DataMember("FunctionName")]
public str parmFunctionName(str _functionName = functionName)
{
    functionName = _functionName;
    return functionName;
}

[DataMember("Arguments"), DataCollection(Types::String)]
public List parmArguments(List _arguments = arguments)
{
    arguments = _arguments;
    return arguments;
}

[DataMember("NoLog")]
public boolean parmNoLog(boolean _noLog = noLog)
{
    noLog = _noLog;
    return noLog;
}
